{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-9796c46e3d1d6002","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"Deterministic pre-submit validation for one strategy's epic decomposition.\n3\t\n4\tChecks the mechanically decidable contract rules that the downstream judges\n5\tand submit.py enforce — the ones an LLM step can silently get wrong while the\n6\tdecomposition still looks good:\n7\t\n8\t  1. Epic body sections: every epic file must carry headings covering\n9\t     Description, Scope, Acceptance Criteria, and HLR Traceability (matched on\n10\t     heading text at any level, exactly like the artifact contract).\n11\t  2. Component vocabulary: every epic's `component` frontmatter value must be\n12\t     verbatim in .context/rhai-components.txt (submit.py silently strips\n13\t     unknown names, leaving the Jira epic component-less).\n14\t  3. Rule 11 (docs-last): every docs-authoring epic must be blocked, directly\n15\t     or transitively, by every main-plan Implementation epic that is not\n16\t     itself docs-authoring.\n17\t  4. Priority inheritance: an epic that directly or transitively enables a P0\n18\t     epic must itself be P0 (docs-authoring epics are exempt; branch epics\n19\t     are conditional alternatives and out of scope).\n20\t  5. Implementation-type parallelism (Rules 7/8/10): no `dependencies` edge,\n21\t     in either direction, between a license-validation and a repo-onboarding\n22\t     epic (Rule 7), a license-validation and a konflux-onboarding epic\n23\t     (Rule 8), or a konflux-onboarding and a general implementation epic\n24\t     (Rule 10) — these pairs must run in parallel; any real coupling is an\n25\t     acceptance-criterion gate, never a DAG edge. Edges into a docs-authoring\n26\t     epic are exempt (Rule 11 requires them).\n27\t\n28\tExit 0 with \"OK\" when clean; exit 1 with one line per violation otherwise.\n29\t\n30\tUsage:\n31\t    python3 skills/epic-decompose/scripts/validate_decomposition.py <STRAT_ID> \\\n32\t        [--artifacts-dir artifacts] [--components .context/rhai-components.txt]\n33\t    python3 skills/epic-decompose/scripts/validate_decomposition.py --self-check\n34\t\"\"\"\n35\t\n36\timport argparse\n37\timport os\n38\timport re\n39\timport sys\n40\t\n41\timport yaml\n42\t\n43\tSECTIONS = [(\"Description\", (\"description\",)),\n44\t            (\"Scope\", (\"scope\",)),\n45\t            (\"Acceptance Criteria\", (\"acceptance criteria\",)),\n46\t            (\"HLR Traceability\", (\"hlr traceability\", \"traceability\"))]\n47\t\n48\tPRIORITY_ORDER = {\"P0\": 0, \"P1\": 1, \"P2\": 2}\n49\t\n50\tIT_ENUM = (\"docs-authoring\", \"konflux-onboarding\", \"license-validation\",\n51\t           \"repo-onboarding\")\n52\t\n53\t# Pairs of implementation kinds that must run in parallel (no DAG edge either\n54\t# way) — parity with the implementation_type_rules judge.\n55\tPARALLEL_PAIRS = {\n56\t    frozenset((\"license-validation\", \"repo-onboarding\")): \"Rule 7\",\n57\t    frozenset((\"license-validation\", \"konflux-onboarding\")): \"Rule 8\",\n58\t    frozenset((\"konflux-onboarding\", \"general\")): \"Rule 10\",\n59\t}\n60\t\n61\tFRONTMATTER_RE = re.compile(r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n62\t\n63\t\n64\tdef read_frontmatter(path):\n65\t    \"\"\"Return (frontmatter dict, body string) for a markdown file.\"\"\"\n66\t    with open(path, encoding=\"utf-8\") as f:\n67\t        content = f.read()\n68\t    m = FRONTMATTER_RE.match(content)\n69\t    if not m:\n70\t        return {}, content\n71\t    try:\n72\t        data = yaml.safe_load(m.group(1))\n73\t    except yaml.YAMLError:\n74\t        return {}, content\n75\t    if not isinstance(data, dict):\n76\t        return {}, content\n77\t    return data, content[m.end():]\n78\t\n79\t\n80\tdef body_headings(body):\n81\t    heads = []\n82\t    for hm in re.finditer(r'^#{1,6}\\s+(.+?)\\s*$', body, re.M):\n83\t        heads.append(re.sub(r'[^a-z ]', '', hm.group(1).lower()).strip())\n84\t    return heads\n85\t\n86\t\n87\tdef load_epics(artifacts_dir, strat_id):\n88\t    \"\"\"Return {epic_key: (path, frontmatter, body)} for one strategy's epics.\n89\t\n90\t    epic_key is the filename stem; branch files carry their BRANCH- prefix.\n91\t    \"\"\"\n92\t    task_dir = os.path.join(artifacts_dir, \"epic-tasks\")\n93\t    if not os.path.isdir(task_dir):\n94\t        return {}\n95\t    pat = re.compile(re.escape(strat_id) + r\"-(BRANCH-[A-Z]-)?(E\\d{3})\\.md$\")\n96\t    epics = {}\n97\t    for name in sorted(os.listdir(task_dir)):\n98\t        m = pat.match(name)\n99\t        if not m:\n100\t            continue\n101\t        path = os.path.join(task_dir, name)\n102\t        fm, body = read_frontmatter(path)\n103\t        epics[name[:-3]] = (path, fm, body)\n104\t    return epics\n105\t\n106\t\n107\tdef dependency_closure(start_key, deps):\n108\t    \"\"\"All epics reachable from start_key by following dependencies.\"\"\"\n109\t    seen, stack = set(), list(deps.get(start_key, []))\n110\t    while stack:\n111\t        n = stack.pop()\n112\t        if n in seen or n not in deps:\n113\t            continue\n114\t        seen.add(n)\n115\t        stack.extend(deps[n])\n116\t    return seen\n117\t\n118\t\n119\tdef check(strat_id, artifacts_dir, components_path):\n120\t    \"\"\"Run all checks; return a list of violation strings.\"\"\"\n121\t    probs = []\n122\t    epics = load_epics(artifacts_dir, strat_id)\n123\t    if not epics:\n124\t        return [\"no epic files found for %s under %s/epic-tasks/\"\n125\t                % (strat_id, artifacts_dir)]\n126\t\n127\t    valid_components = set()\n128\t    if os.path.isfile(components_path):\n129\t        with open(components_path, encoding=\"utf-8\") as f:\n130\t            valid_components = {ln.strip() for ln in f if ln.strip()}\n131\t    if not valid_components:\n132\t        probs.append(\"cannot read canonical component list %s — verify the \"\n133\t                     \"path before trusting component names\" % components_path)\n134\t\n135\t    deps, is_branch, is_docs, is_impl, itype, prio = {}, {}, {}, {}, {}, {}\n136\t    for key, (path, fm, body) in epics.items():\n137\t        name = key + \".md\"\n138\t        # 1. body sections (contract parity with the artifact judge)\n139\t        heads = body_headings(body)\n140\t        for want, aliases in SECTIONS:\n141\t            if not any(a in h for h in heads for a in aliases):\n142\t                probs.append(\"%s: body missing '%s' section (required \"\n143\t                             \"sections: Description, Scope, Acceptance \"\n144\t                             \"Criteria, HLR Traceability)\" % (name, want))\n145\t        # 2. component vocabulary\n146\t        comp = fm.get(\"component\")\n147\t        if valid_components and isinstance(comp, str) and comp.strip() \\\n148\t                and comp.strip() not in valid_components:\n149\t            probs.append(\"%s: component '%s' is not in %s — pick the closest \"\n150\t                         \"canonical name (submit.py strips unknown names)\"\n151\t                         % (name, comp.strip(), components_path))\n152\t        # collect graph facts\n153\t        dl = fm.get(\"dependencies\")\n154\t        deps[key] = [x for x in dl if isinstance(x, str)] \\\n155\t            if isinstance(dl, list) else []\n156\t        is_branch[key] = \"BRANCH-\" in key\n157\t        is_docs[key] = fm.get(\"implementation_type\") == \"docs-authoring\"\n158\t        is_impl[key] = fm.get(\"type\") == \"Implementation\"\n159\t        it = fm.get(\"implementation_type\")\n160\t        itype[key] = it if it in IT_ENUM else None\n161\t        prio[key] = fm.get(\"priority\")\n162\t\n163\t    def kind(key):\n164\t        \"\"\"Implementation kind of an epic — parity with the judge: an epic\n165\t        that is not type Implementation is never a parallel-rule party; an\n166\t        Implementation epic's kind is its implementation_type when that is a\n167\t        known label, else 'general'.\"\"\"\n168\t        if not is_impl[key]:\n169\t            return \"non-implementation\"\n170\t        return itype[key] or \"general\"\n171\t\n172\t    # 3. Rule 11 — docs-authoring blocked by every main-plan Implementation\n173\t    universe = [k for k in epics\n174\t                if is_impl[k] and not is_docs[k] and not is_branch[k]]\n175\t    for k in sorted(epics):\n176\t        if not is_docs[k]:\n177\t            continue\n178\t        cl = dependency_closure(k, deps)\n179\t        missing = sorted(e for e in universe if e != k and e not in cl)\n180\t        if missing:\n181\t            probs.append(\"Rule 11: docs-authoring %s is not blocked by every \"\n182\t                         \"Implementation epic — add %s to its dependency chain\"\n183\t                         % (k, \", \".join(missing)))\n184\t\n185\t    # 4. Priority inheritance — enablers of P0 work must be P0\n186\t    for k in sorted(epics):\n187\t        if is_branch[k] or is_docs[k]:\n188\t            continue\n189\t        if prio.get(k) != \"P0\":\n190\t            continue\n191\t        # every main-plan, non-docs epic in k's closure enables P0 work\n192\t        cl = dependency_closure(k, deps)\n193\t        for t in sorted(cl):\n194\t            if is_branch[t] or is_docs[t]:\n195\t                continue\n196\t            if PRIORITY_ORDER.get(prio.get(t), 9) > 0:\n197\t                probs.append(\"priority inheritance: %s (%s) blocks P0 epic %s \"\n198\t                             \"but is %s — raise it to P0 or restructure\"\n199\t                             % (t, prio.get(t), k, prio.get(t)))\n200\t\n201\t    # 5. Rules 7/8/10 — implementation-type parallelism: the mandated-parallel\n202\t    #    pairs carry no dependencies edge in either direction (direct edges\n203\t    #    only; edges into a docs-authoring epic are exempt — Rule 11 requires\n204\t    #    them; dependencies naming epics with no file cannot be jud